// ListBox — Gtk.ListBox
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles list with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"
import type { ListTabBehavior, SelectionMode } from "@/lib/enums"

export interface ListBoxProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** gboolean, from Gtk.ListBox */
  acceptUnpairedRelease?: boolean

  /** gboolean, from Gtk.ListBox */
  activateOnSingleClick?: boolean

  /** SelectionMode, from Gtk.ListBox */
  selectionMode?: SelectionMode

  /** gboolean, from Gtk.ListBox */
  showSeparators?: boolean

  /** ListTabBehavior, from Gtk.ListBox */
  tabBehavior?: ListTabBehavior
}

export function ListBox({ className, children }: ListBoxProps) {
  return (
    <div className={cn("text-[var(--view-fg-color)]", "bg-[var(--view-bg-color)]", "bg-clip-padding", "border-[color-mix(in_srgb,currentColor_var(--border-opacity),transparent)]", "shadow-none", className)}>
      {children}
    </div>
  )
}
